/**
 * ORDEN: the three rooms, rendered in Blender Cycles. Each room holds several
 * products; the first one is the room's main piece.
 *
 * Every room ships, under public/rooms/<id>/ (generated by `npm run assets`
 * from blender/renders/final/), for each Blender camera:
 *   <shot>-beauty   Cycles still, every product in place (default view)
 *   <shot>-plate    the same view without any of the room's products: the
 *                   real-time GLBs are drawn over it
 *   <shot>-depth    depth (white = near) for the parallax
 * where <shot> is "room", "product" (main piece) or "product-<id>", with
 * "-p" for the 9:16 phone stills; plus probe-<id>.hdr, a light probe taken
 * where each product stands. src/config/scenes/<id>.json holds the cameras
 * (three.js coordinates, Y-up, vertical fov) and each product's placement.
 */
import type { ProductId } from "./products";
import living from "./scenes/living.json";
import bedroom from "./scenes/bedroom.json";
import storage from "./scenes/storage.json";
import { asset } from "@/config/site";

export type RoomId = "living" | "bedroom" | "storage";

export interface SceneCamera {
  position: [number, number, number];
  quaternion: [number, number, number, number];
  /** Vertical field of view, degrees, for its frame (16:9 or 9:16). */
  fov: number;
}

export interface ScenePlacement {
  position: [number, number, number];
  rotation_y: number;
  /** Name of the Blender camera that frames this product. */
  camera: string;
}

export interface RoomScene {
  resolution: [number, number];
  depth: { near: number; far: number };
  products: Partial<Record<ProductId, ScenePlacement>>;
  cameras: Record<string, SceneCamera>;
}

export interface Room {
  id: RoomId;
  index: string;
  name: string;
  /** Display title of the room view. */
  title: string;
  /** Short line under the room name. */
  mood: string;
  /** Products in this room, main piece first. */
  productIds: ProductId[];
  scene: RoomScene;
  /** Blender exposure (stops) used for the stills: the live products match it. */
  exposure: number;
}

const asScene = (s: unknown) => s as RoomScene;

export const ROOMS: Room[] = [
  {
    id: "living",
    index: "01",
    name: "Living",
    title: "The Living Room",
    mood: "Daylight, wool and stone.",
    productIds: ["coffee-table", "sofa"],
    scene: asScene(living),
    exposure: 0.7,
  },
  {
    id: "bedroom",
    index: "02",
    name: "Bedroom",
    title: "The Bedroom",
    mood: "Linen, low light, close at hand.",
    productIds: ["bedside-table", "headboard-shelf"],
    scene: asScene(bedroom),
    exposure: 0.85,
  },
  {
    id: "storage",
    index: "03",
    name: "Dressing",
    title: "The Dressing Room",
    mood: "A calm volume for what you keep.",
    productIds: ["wardrobe", "shoe-bench"],
    scene: asScene(storage),
    exposure: 0.75,
  },
];

export const ROOM_MAP = Object.fromEntries(ROOMS.map((r) => [r.id, r])) as Record<RoomId, Room>;

/** landscape = the 16:9 stills; portrait = the 9:16 stills rendered for phones. */
export type Orientation = "landscape" | "portrait";

/** The room view, or the view of one product. */
export type Shot = "room" | ProductId;

/** Blender camera name of a shot, for this orientation. */
export function cameraName(room: RoomId, shot: Shot, o: Orientation): string {
  const base = shot === "room" ? "cam_room" : (ROOM_MAP[room].scene.products[shot]?.camera ?? "cam_product");
  const portrait = `${base}_p`;
  return o === "portrait" && ROOM_MAP[room].scene.cameras[portrait] ? portrait : base;
}

export function sceneCamera(room: RoomId, shot: Shot, o: Orientation): SceneCamera {
  return ROOM_MAP[room].scene.cameras[cameraName(room, shot, o)];
}

/** cam_room -> room, cam_product_sofa_p -> product-sofa-p (see scripts/prepare-web-assets.mjs). */
export const cameraSlug = (name: string) => name.replace(/^cam_/, "").replace(/_p$/, "-p").replace(/_/g, "-");

export function roomAsset(room: RoomId, shot: Shot, kind: "beauty" | "plate" | "depth", o: Orientation = "landscape") {
  return asset(`/rooms/${room}/${cameraSlug(cameraName(room, shot, o))}-${kind}.webp`);
}

export const hasPortrait = (room: RoomId) => !!ROOM_MAP[room].scene.cameras.cam_room_p;

export const probeUrl = (room: RoomId, product: ProductId) => asset(`/rooms/${room}/probe-${product}.hdr`);

/** Where a product stands in its room (three.js coordinates). */
export const placement = (room: RoomId, product: ProductId) => ROOM_MAP[room].scene.products[product]!;

export const roomOf = (product: ProductId) => ROOMS.find((r) => r.productIds.includes(product))!;

/** The stage keeps the stills' frame and covers the viewport with it. */
export const FRAME_ASPECT = 16 / 9;
export const aspectOf = (o: Orientation) => (o === "portrait" ? 9 / 16 : FRAME_ASPECT);
